import { serve } from 'https://deno.land/std@0.177.0/http/server.ts'
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
}

serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })

  try {
    const { informe_id } = await req.json()
    if (!informe_id) throw new Error('informe_id requerido')

    const admin = createClient(
      Deno.env.get('SUPABASE_URL')!,
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,
    )

    const { data: informe, error: infErr } = await admin
      .from('informes')
      .select('*, alumno:alumnos(nivel, usuario:usuarios(nombre, apellidos))')
      .eq('id', informe_id)
      .single()
    if (infErr) throw new Error('Informe no encontrado: ' + infErr.message)

    const { ia, kpis } = informe.contenido || {}
    if (!ia || !kpis) throw new Error('El informe no tiene contenido generado')

    const u = informe.alumno?.usuario as any
    const alumnoNombre = u ? `${u.nombre} ${u.apellidos || ''}`.trim() : 'Alumno'

    const html = generarHtml(informe, ia, kpis, alumnoNombre)

    const supabaseUrl = Deno.env.get('SUPABASE_URL')!
    const pdfUrl = `${supabaseUrl}/functions/v1/ver-informe?id=${informe_id}`

    const { error: updErr } = await admin.from('informes').update({
      estado: 'visible',
      visible: true,
      html_cache: html,
      pdf_url: pdfUrl,
      archivo_url: pdfUrl,
      published_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    }).eq('id', informe_id)
    if (updErr) throw new Error('Error al publicar: ' + updErr.message)

    return new Response(
      JSON.stringify({ success: true, pdf_url: pdfUrl }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    )

  } catch (err: any) {
    console.error('publicar-informe error:', err)
    return new Response(
      JSON.stringify({ error: err?.message || 'Error desconocido' }),
      { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
    )
  }
})

const MESES = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre']
const LOGO_SRC = 'data:image/png;base64,'
const SUBJ_COLORS = [
  'linear-gradient(120deg, #154ca9, #04071b)',
  'linear-gradient(120deg, #2f9e6f, #146b46)',
  'linear-gradient(120deg, #d99a3e, #8b5e10)',
  'linear-gradient(120deg, #6e40c9, #3d1c8a)',
]

function fmtFecha(d: string) {
  const dt = new Date(d)
  return `${dt.getUTCDate()} de ${MESES[dt.getUTCMonth()]} de ${dt.getUTCFullYear()}`
}

function escHtml(s: string) {
  return (s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
}

function makeEvolutionData(n: number, avgAutonomia: number | null, tendencia: string | null): number[] {
  const avg = avgAutonomia != null ? Math.round(avgAutonomia * 10) : 50
  if (n <= 1) return [avg]
  if (tendencia === 'mejora') {
    const start = Math.max(10, avg - 15), end = Math.min(100, avg + 10)
    return Array.from({ length: n }, (_, i) => Math.round(start + (end - start) * (i / (n - 1))))
  }
  if (tendencia === 'empeora') {
    const start = Math.min(95, avg + 15), end = Math.max(10, avg - 10)
    return Array.from({ length: n }, (_, i) => Math.round(start + (end - start) * (i / (n - 1))))
  }
  return Array.from({ length: n }, () => avg)
}

function generarHtml(informe: any, ia: any, kpis: any, alumnoNombre: string): string {
  const global = kpis.global || {}
  const kpisAsigs: any[] = kpis.asignaturas || []
  const iaAsigs: any[] = ia.asignaturas || []

  const tipoLabel = informe.tipo === 'mensual' ? 'Informe mensual' : 'Informe personalizado'
  const mesLabel = informe.tipo === 'mensual'
    ? new Date(informe.fecha_inicio).toLocaleDateString('es-ES', { month: 'long', year: 'numeric', timeZone: 'UTC' })
    : `${fmtFecha(informe.fecha_inicio)} – ${fmtFecha(informe.fecha_fin)}`

  const subjects = kpisAsigs.map((kAsig: any) => {
    const iAsig = iaAsigs.find((a: any) => a.nombre === kAsig.nombre) || {}
    const mejoras = (ia.puntos_mejora || []).filter((p: any) => p.asignatura === kAsig.nombre)
    return { ...kAsig, ia: iAsig, mejoras }
  })

  const chartInits: string[] = []

  const subjectHtml = subjects.map((subj: any, idx: number) => {
    const color = SUBJ_COLORS[idx % SUBJ_COLORS.length]
    const chartId = `chart-asig-${idx}`
    const numSessions = subj.num_sesiones || 1
    const evolData = makeEvolutionData(numSessions, subj.valoraciones?.autonomia ?? null, subj.tendencia_autonomia ?? null)
    const evolLabels = evolData.map((_: number, i: number) => `S${i + 1}`)
    const chartColor = idx % 2 === 0 ? '#154ca9' : '#2f9e6f'

    chartInits.push(
      `new Chart(document.getElementById('${chartId}'), {` +
      `type:'bar',` +
      `data:{labels:${JSON.stringify(evolLabels)},datasets:[{data:${JSON.stringify(evolData)},backgroundColor:'${chartColor}',borderRadius:5,barThickness:22}]},` +
      `options:{responsive:true,plugins:{legend:{display:false}},` +
      `scales:{y:{min:0,max:100,grid:{color:'rgba(4,7,27,0.06)'},ticks:{color:'#154ca9',font:{size:10}}},` +
      `x:{grid:{display:false},ticks:{color:'#154ca9',font:{size:10}}}}}});`
    )

    const temas: string[] = subj.temas_trabajados?.length ? subj.temas_trabajados : (subj.ia?.temas_trabajados || [])
    const totalHoras = subj.horas_totales || 1
    const temasHtml = temas.length > 0
      ? temas.map((tema: string) => {
          const pct = Math.round(100 / temas.length)
          const h = Math.round((totalHoras / temas.length) * 10) / 10
          return `<div class="tema-row">
            <div class="tema-nombre">${escHtml(tema)}</div>
            <div class="tema-bar-bg"><div class="tema-bar-fill${idx % 2 === 1 ? ' green' : ''}" style="width:${pct}%"></div></div>
            <div class="tema-horas">${h}h</div>
          </div>`
        }).join('')
      : `<div class="tema-row"><div class="tema-nombre" style="opacity:.6;font-style:italic">Sin temas registrados</div></div>`

    const analisisHtml = subj.ia?.analisis
      ? `<p style="font-size:0.97rem;margin-bottom:20px">${escHtml(subj.ia.analisis)}</p>`
      : ''

    const mejorasHtml = subj.mejoras.length > 0
      ? `<div class="puntos-grupo mejora">
          <h3>Puntos a mejorar</h3>
          ${subj.mejoras.map((m: any, mi: number) => `<div class="mejora-item"><div class="mejora-orden">${m.prioridad || mi + 1}</div><div>${escHtml(m.descripcion)}</div></div>`).join('')}
        </div>`
      : ''

    const recomMot = subj.ia?.horas_recomendacion?.motivo || ''
    const recomHtml = recomMot
      ? `<div class="practica-casa">
          <div class="titulo">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M3 11.5 12 4l9 7.5"/><path d="M5 10v10h14V10"/></svg>
            Recomendación
          </div>
          <p style="font-size:0.92rem">${escHtml(recomMot)}</p>
        </div>`
      : ''

    const avgPorSesion = subj.num_sesiones && subj.horas_totales
      ? (subj.horas_totales / subj.num_sesiones).toFixed(1) + 'h'
      : '—'

    return `
  <div class="subj-banner" style="background:${color};margin-top:46px;border-radius:16px;padding:30px 34px;color:#fff">
    <h2 style="font-family:'Playfair Display',serif;font-size:2.1rem;font-weight:700;color:#fff;text-transform:uppercase;letter-spacing:.03em;margin-bottom:6px">${escHtml(subj.nombre)}</h2>
    ${subj.profesor ? `<div class="subj-meta">${escHtml(subj.profesor)}</div>` : ''}
  </div>
  <div class="subj-content">
    <div class="mini-kpi-row">
      <div class="mini-kpi"><div class="num">${subj.horas_totales || '—'}h</div><div class="label">Horas dedicadas</div></div>
      <div class="mini-kpi"><div class="num">${subj.num_sesiones || '—'}</div><div class="label">Sesiones</div></div>
      <div class="mini-kpi"><div class="num">${avgPorSesion}</div><div class="label">Media por sesión</div></div>
      ${subj.nota_media != null ? `<div class="mini-kpi"><div class="num">${subj.nota_media.toFixed(1)}</div><div class="label">Nota estimada</div></div>` : ''}
    </div>
    <div class="temas-tabla">${temasHtml}</div>
    ${analisisHtml}
    ${mejorasHtml}
    ${recomHtml}
    <div class="evolucion-wrap">
      <div class="subtitulo">Evolución de autonomía en el periodo (escala 0–100)</div>
      <canvas class="evolucion-chart" id="${chartId}"></canvas>
    </div>
  </div>`
  }).join('')

  const puntosFuertesHtml = (ia.puntos_fuertes || []).length > 0
    ? `<div class="puntos-grupo fuertes">
        <h3>Puntos fuertes del periodo</h3>
        <ul class="puntos-lista">
          ${(ia.puntos_fuertes as string[]).map((p: string) => `<li>${escHtml(p)}</li>`).join('')}
        </ul>
      </div>`
    : ''

  const objetivosHtml = (ia.objetivos_siguiente_periodo || []).length > 0
    ? `<div class="puntos-grupo mejora" style="margin-top:20px">
        <h3>Objetivos del siguiente periodo</h3>
        ${(ia.objetivos_siguiente_periodo as string[]).map((o: string, i: number) => `<div class="mejora-item"><div class="mejora-orden">${i + 1}</div><div>${escHtml(o)}</div></div>`).join('')}
      </div>`
    : ''

  const planHtml = iaAsigs.length > 0
    ? `<div class="conclu-block">
        <div class="conclu-eyebrow">Propuesta de organización</div>
        <h3 style="font-family:'Playfair Display',serif;font-size:1.2rem;margin-bottom:14px">Plan para el siguiente periodo</h3>
        <div class="plan-comparativa">
          <div class="plan-col propuesta">
            <h4>Recomendación por asignatura</h4>
            ${iaAsigs.map((a: any) => {
              const dir = a.horas_recomendacion?.direccion || 'mantener'
              const tagClass = dir === 'aumentar' ? 'tag-aumentar' : 'tag-mantener'
              const tagLabel = dir === 'aumentar' ? 'Aumentar' : dir === 'reducir' ? 'Reducir' : 'Mantener'
              return `<div class="plan-item">
                <span class="asig">${escHtml(a.nombre)}</span><span class="tag-cambio ${tagClass}">${tagLabel}</span>
                ${a.horas_recomendacion?.motivo ? `<div class="motivo-cambio">${escHtml(a.horas_recomendacion.motivo)}</div>` : ''}
              </div>`
            }).join('')}
          </div>
        </div>
      </div>`
    : ''

  const topMejora = [...(ia.puntos_mejora || [])].sort((a: any, b: any) => a.prioridad - b.prioridad)[0]
  const highlightHtml = topMejora
    ? `<div class="highlight-card wrap-inner">
        <svg class="icono" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">
          <path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/>
          <line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/>
        </svg>
        <div class="txt">
          <div class="eyebrow">Prioridad principal este periodo</div>
          <div class="valor">${escHtml(topMejora.asignatura)}: <span>${escHtml(topMejora.tema)}</span></div>
        </div>
      </div>`
    : ''

  const totalProfs = (global.profesores_distintos || []).length

  return `<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>${escHtml(tipoLabel)} — ${escHtml(alumnoNombre)}</title>
<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,500;0,700;1,500&family=Lora:ital,wght@0,400;0,500;0,600;1,400&display=swap" rel="stylesheet">
<script src="https://cdn.jsdelivr.net/npm/chart.js"><\/script>
<style>
  :root{--navy-deep:#04071b;--blue:#154ca9;--blue-light:#6eaef0;--cream:#f4f1e8;--white:#ffffff;--green-deep:#146b46;--green:#2f9e6f;--green-light:#6fcf9e;--amber:#d99a3e;--amber-deep:#a9701e;--alert:#c1502e}
  *{box-sizing:border-box;margin:0;padding:0}
  html,body{background:var(--white)}
  body{font-family:'Lora',serif;color:var(--navy-deep);line-height:1.65}
  .wrap{max-width:900px;margin:0 auto;padding:0 24px 60px}
  .wrap-inner{max-width:900px;margin:0 auto;padding:0 24px}
  .logo-top{text-align:center;padding:40px 24px 6px}
  .logo-top img{height:78px;border-radius:10px;box-shadow:0 8px 24px rgba(4,7,27,.18)}
  .titulo-block{text-align:center;padding:30px 24px 8px}
  .titulo-block .eyebrow{font-size:.78rem;letter-spacing:.14em;text-transform:uppercase;color:var(--blue);font-weight:600;margin-bottom:10px}
  .titulo-block h1{font-family:'Playfair Display',serif;font-weight:700;font-size:2.15rem;color:var(--navy-deep);margin-bottom:8px}
  .titulo-block .periodo{font-size:1rem;color:var(--navy-deep);opacity:.6}
  .kpi-strip{display:flex;gap:14px;margin:30px 0;flex-wrap:wrap}
  .kpi-card{flex:1;min-width:130px;background:var(--white);border:1px solid var(--cream);border-top:3px solid var(--blue);border-radius:10px;padding:18px 14px}
  .kpi-card .num{font-family:'Playfair Display',serif;font-size:1.7rem;font-weight:700;color:var(--navy-deep)}
  .kpi-card .label{font-size:.74rem;text-transform:uppercase;letter-spacing:.05em;color:var(--navy-deep);opacity:.55;margin-top:3px}
  .highlight-card{background:linear-gradient(120deg,var(--navy-deep),var(--blue));border-radius:12px;padding:22px 24px;margin:0 24px 6px;max-width:852px;margin-left:auto;margin-right:auto;color:var(--white);display:flex;align-items:center;gap:16px}
  .highlight-card .icono{width:30px;height:30px;color:var(--blue-light);flex-shrink:0}
  .highlight-card .txt .eyebrow{font-size:.72rem;text-transform:uppercase;letter-spacing:.08em;opacity:.75;margin-bottom:4px}
  .highlight-card .txt .valor{font-family:'Playfair Display',serif;font-size:1.25rem;font-weight:700}
  .highlight-card .txt .valor span{color:var(--blue-light)}
  section{background:var(--white);border:1px solid var(--cream);border-radius:12px;padding:30px;margin-top:24px;box-shadow:0 3px 20px rgba(4,7,27,.05)}
  h2{font-family:'Playfair Display',serif;font-size:1.35rem;color:var(--navy-deep);margin-bottom:14px}
  p{margin-bottom:10px;font-size:.97rem}
  .subj-meta{font-size:.92rem;opacity:.85}
  .subj-content{border:1px solid var(--cream);border-top:none;border-radius:0 0 12px 12px;padding:30px 34px 34px;margin-top:-2px;box-shadow:0 3px 20px rgba(4,7,27,.05)}
  .temas-tabla{margin:4px 0 24px}
  .tema-row{display:flex;align-items:center;gap:14px;padding:10px 0;border-bottom:1px solid var(--cream)}
  .tema-row:last-child{border-bottom:none}
  .tema-nombre{flex:0 0 190px;font-weight:600;font-size:.92rem}
  .tema-bar-bg{flex:1;height:8px;background:var(--cream);border-radius:5px;overflow:hidden}
  .tema-bar-fill{height:100%;background:linear-gradient(90deg,var(--blue),var(--blue-light));border-radius:5px}
  .tema-bar-fill.green{background:linear-gradient(90deg,var(--green-deep),var(--green-light))}
  .tema-horas{flex:0 0 60px;text-align:right;font-size:.85rem;color:var(--blue);font-weight:600}
  .puntos-grupo{margin-bottom:20px}
  .puntos-grupo h3{font-family:'Lora',serif;font-size:.8rem;font-weight:700;text-transform:uppercase;letter-spacing:.06em;margin-bottom:10px}
  .puntos-grupo.fuertes h3{color:var(--green-deep)}
  .puntos-grupo.mejora h3{color:var(--blue)}
  ul.puntos-lista{list-style:none}
  ul.puntos-lista li{position:relative;padding-left:18px;margin-bottom:8px;font-size:.94rem}
  ul.puntos-lista li::before{content:"—";position:absolute;left:0;opacity:.5}
  .mejora-item{display:flex;gap:12px;margin-bottom:10px;align-items:baseline}
  .mejora-orden{font-family:'Playfair Display',serif;font-weight:700;color:var(--blue-light);font-size:1.1rem;min-width:20px}
  .practica-casa{background:var(--cream);border-radius:10px;padding:16px 18px;margin-top:4px;margin-bottom:20px}
  .practica-casa .titulo{display:flex;align-items:center;gap:8px;font-size:.8rem;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--navy-deep);opacity:.75;margin-bottom:10px}
  .practica-casa .titulo svg{width:16px;height:16px;color:var(--blue);opacity:1}
  .practica-casa p{font-size:.92rem}
  .evolucion-wrap .subtitulo{font-size:.85rem;color:var(--blue);margin-bottom:10px;font-weight:500}
  canvas.evolucion-chart{max-height:150px}
  .conclu-block{margin-top:28px}
  .conclu-eyebrow{font-size:.76rem;text-transform:uppercase;letter-spacing:.08em;color:var(--blue);font-weight:700;margin-bottom:8px}
  .mini-kpi-row{display:flex;gap:12px;margin-bottom:16px;flex-wrap:wrap}
  .mini-kpi{flex:1;min-width:130px;background:var(--cream);border-radius:8px;padding:12px 14px}
  .mini-kpi .num{font-family:'Playfair Display',serif;font-size:1.3rem;font-weight:700;color:var(--navy-deep)}
  .mini-kpi .label{font-size:.72rem;color:var(--navy-deep);opacity:.6;text-transform:uppercase;letter-spacing:.04em}
  .plan-comparativa{display:flex;gap:20px;margin-bottom:6px;flex-wrap:wrap}
  .plan-col{flex:1;min-width:240px}
  .plan-col h4{font-family:'Playfair Display',serif;font-style:italic;font-size:1rem;color:var(--blue);margin-bottom:10px}
  .plan-item{font-size:.92rem;padding:8px 0;border-bottom:1px solid var(--cream)}
  .plan-item .asig{font-weight:600}
  .plan-col.propuesta .plan-item{background:var(--cream);border-radius:8px;padding:10px 12px;border:none;margin-bottom:8px}
  .tag-cambio{display:inline-block;font-size:.72rem;font-weight:700;padding:2px 8px;border-radius:10px;margin-left:8px;text-transform:uppercase;letter-spacing:.03em}
  .tag-aumentar{background:rgba(217,154,62,.18);color:var(--amber-deep)}
  .tag-mantener{background:rgba(47,158,111,.15);color:var(--green-deep)}
  .motivo-cambio{font-size:.88rem;color:var(--navy-deep);opacity:.7;margin-top:4px}
  footer{text-align:center;margin-top:40px;padding:20px;font-size:.8rem;color:var(--blue);opacity:.6}
  @media(max-width:600px){.kpi-strip{flex-wrap:wrap}.tema-nombre{flex:0 0 120px}}
</style>
</head>
<body>

<div class="logo-top"><img src="${LOGO_SRC}" alt="Nexo Académico"></div>

<div class="titulo-block wrap-inner">
  <div class="eyebrow">${escHtml(tipoLabel)}</div>
  <h1>${escHtml(alumnoNombre)}</h1>
  <div class="periodo">${escHtml(mesLabel)}</div>
</div>

<div class="wrap-inner">
  <div class="kpi-strip">
    <div class="kpi-card"><div class="num">${global.total_sesiones ?? '—'}</div><div class="label">Sesiones</div></div>
    <div class="kpi-card"><div class="num">${global.total_horas ?? '—'}h</div><div class="label">Horas totales</div></div>
    <div class="kpi-card"><div class="num">${global.asignaturas_distintas ?? '—'}</div><div class="label">Asignaturas</div></div>
    <div class="kpi-card"><div class="num">${totalProfs}</div><div class="label">${totalProfs === 1 ? 'Profesor' : 'Profesores'}</div></div>
  </div>
</div>

${highlightHtml}

<div class="wrap">
  ${subjectHtml}

  <section style="margin-top:46px">
    <h2>Conclusiones del periodo</h2>

    ${ia.resumen_ejecutivo ? `<p style="font-size:1.02rem;margin-bottom:24px">${escHtml(ia.resumen_ejecutivo)}</p>` : ''}

    ${puntosFuertesHtml}

    ${ia.patron_trabajo ? `<div class="conclu-block"><div class="conclu-eyebrow">Patrón de trabajo</div><p>${escHtml(ia.patron_trabajo)}</p></div>` : ''}

    ${objetivosHtml}

    ${planHtml}
  </section>
</div>

<footer>Nexo Académico · nexoacademico.es · nexoacademicopremium@gmail.com · 611 49 25 92<br>Informe generado el ${new Date().toLocaleDateString('es-ES', { day: 'numeric', month: 'long', year: 'numeric' })}</footer>

<script>
${chartInits.join('\n')}
<\/script>
</body>
</html>`
}
